TLM.f("Commune/Propaganda",{"officium":"Pro Propagatione Fidei","rule":["Sub unica conclusione in commemoratione"],"sections":{"Introitus":[{"k":"ref","la":"Ps 66:2-3"},{"k":"text","la":"Deus misereátur nostri, et benedícat nobis: illúminet vultum suum super nos, et misereátur nostri: ut cognoscámus in terra viam tuam, in ómnibus géntibus salutáre tuum. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps ibid., 4"},{"k":"text","la":"Confiteántur tibi pópuli, Deus: confiteántur tibi pópuli omnes."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Deus misereátur nostri, et benedícat nobis: illúminet vultum suum super nos, et misereátur nostri: ut cognoscámus in terra viam tuam, in ómnibus géntibus salutáre tuum. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Deus, qui omnes hómines vis salvos fíeri, et ad agnitiónem veritátis veníre: mitte, quǽsumus, operários in messem tuam, et da eis cum omni fidúcia loqui verbum tuum; ut sermo tuus currat et clarificétur, et omnes gentes cognóscant te solum Deum verum, et quem misísti Jesum Christum Fílium tuum, Dóminum nostrum."},{"k":"macro","name":"Qui tecum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiae"},{"k":"ref","la":"Eccli 36:1-10,17-19"},{"k":"text","la":"Miserére nostri, Deus ómnium, et réspice nos, et osténde nobis lucem miseratiónum tuárum: et immítte timórem tuum super gentes, quae non exquisiérunt te, ut cognóscant quia non est Deus nisi tu, et enárrent magnália tua. Alleva manum tuam super gentes aliénas, ut vídeant poténtiam tuam. Sicut enim in conspéctu eórum sanctificátus es in nobis, sic in conspéctu nostro magnificáberis in eis, ut cognóscant te, sicut et nos cognóvimus, quóniam non est Deus praeter te, Dómine. Innova signa, et immúta mirabília. Glorífica manum et bráchium dextrum. Excita furórem, et effúnde iram. Tolle adversárium, et afflíge inimícum. Festína tempus, et meménto finis, ut enárrent mirabília tua. Da testimónium his, qui ab inítio creatúrae tuae sunt, et súscita praedicatiónes, quas locúti sunt in nómine tuo prophétae prióres. Da mercédem sustinéntibus te, ut prophétae tui fidéles inveniántur: et exáudi oratiónes servórum tuórum, secúndum benedictiónem Aaron de pópulo tuo, et dírige nos in viam justítiae, et sciant omnes, qui hábitant terram, quia tu es Deus conspéctor saeculórum."}],"Graduale":[{"k":"ref","la":"Ps 66:6-8"},{"k":"text","la":"Confiteántur tibi pópuli, Deus: confiteántur tibi pópuli omnes: terra dedit fructum suum."},{"k":"text","la":"Benedícat nos Deus, Deus noster, benedícat nos Deus: et métuant eum omnes fines terrae.","mark":"V"},{"k":"text","la":"Allelúja , allelúja."},{"k":"ref","la":"Ps 99:1"},{"k":"text","la":"Jubiláte Deo, omnis terra: servíte Dómino in laetítia: introíte in conspéctu ejus, in exsultatióne. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 99:1-2"},{"k":"text","la":"Jubiláte Deo, omnis terra: servíte Dómino in laetítia: introíte in conspéctu ejus, in exsultatióne. Allelúja."},{"k":"text","la":"Scitóte quóniam Dóminus ipse est Deus: ipse fecit nos, et non ipsi nos. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 95:3-5"},{"k":"text","la":"Annuntiáte inter gentes glóriam Dómini, in ómnibus pópulis mirabília ejus."},{"k":"text","la":"Quóniam magnus Dóminus, et laudábilis nimis: terríbilis est super omnes deos.","mark":"V"},{"k":"text","la":"Quóniam omnes dii géntium daemónia: Dóminus autem caelos fecit.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthaéum"},{"k":"ref","la":"Matt 9:35-38"},{"k":"text","la":"In illo témpore: Circuíbat Jesus omnes civitátes et castélla, docens in synagógis eórum, et praédicans Evangélium regni, et curans omnem languórem et omnem infirmitátem. Videns autem turbas, misértus est eis: quia erant vexáti et jacéntes sicut oves non habéntes pastórem. Tunc dicit discípulis suis: Messis quidem multa, operárii autem pauci. Rogáte ergo Dóminum messis, ut mittat operários in messem suam."}],"Offertorium":[{"k":"ref","la":"Ps 95:7-9"},{"k":"text","la":"Afférte Dómino, pátriae géntium, afférte Dómino glóriam et honórem, afférte Dómino glóriam nómini ejus: tóllite hóstias, et introíte in átria ejus: adoráte Dóminum in átrio sancto ejus. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Protéctor noster, áspice, Deus, et réspice in fáciem Christi tui, qui dedit redemptiónem semetípsum pro ómnibus: et fac, ut ab ortu solis usque ad occásum magnificétur nomen tuum in géntibus, ac in omni loco sacrificétur, et offerátur nómini tuo oblátio munda."},{"k":"macro","name":"Per eundem"}],"Communio":[{"k":"ref","la":"Ps 116:1-2"},{"k":"text","la":"Laudáte Dóminum, omnes gentes: laudáte eum, omnes pópuli: quóniam confirmáta est super nos misericórdia ejus, et véritas Dómini manet in aetérnum. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Redemptiónis nostræ múnere vegetáti: quǽsumus, Dómine; ut hoc perpétuæ salútis auxílio, fides semper vera profíciat."},{"k":"macro","name":"Per Dominum"}]},"hr":{"4411f3a5954d5709":{"t":"Bože, koji hoćeš da se svi ljudi spase i da spoznaju istinu; pošalji, molimo, radnike u svoju žetvu i daj iim da s velikim pouzdanjem navješćuju tvoju riječ, te tvoja istina bude brzo proslavljena i svi narodi upoznaju tebe, jedinoga pravoga Boga, i onoga, koga si poslao, Isusa Krista, Sina tvoga.\n<i>Koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji hoćeš, da se svi ljudi spasu i da spoznaju istinu, pošalji, molimo, radnike u svoju žetvu i daj im, da s punim pouzdanjem navijestaju nječ Tvoju, te riječ Tvoja brzo bude proslavljena i svi narodi upoznaju Tebe, jedinoga pravoga Boga, i Onoga, koga si poslao, Isusa Kriata. Sina Tvoga, koji s tobom živi 1 kraljuje","knRef":"Kniewald 1942, str. 842–843 (snimka 422) (OCR)"},"0a8bc7b46df4fa9d":{"t":"Pogledaj, zaštitniče naš Bože, i obazri se na lice Krista svoga koji je samoga sebe dao kao otkup za sve ljude, te učini da od istoka sunčanoga do zapada narodi veličaju tvoje ime i da se na svakom mjestu prinosi i prikazuje tvojemu imenu čista žrtva.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Pogledaj, zaštitnice naš, Bože, i vidi lice Krista svoga, koji je samoga sebe dao kao otkup za sve ljude, pa učini, da od istoka sunčanoga do zapada narodi veličaju Ime Tvoje i da se na sva- kom mjestu prinosi i posvećuje Imenu Tvomu žrtva čista, po istom G. n.","knRef":"Kniewald 1942, str. 844–845 (snimka 423) (OCR)"},"c4cfab681aef848f":{"t":"<i>Pomolimo se</i>.\nRedemptiónis nostrae múnere vegetáti, quaésumus, Dómine: ut hoc perpétuae salútis auxílio fides semper vera profíciat.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
